#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

/*
 * Fast dominant eigenpair for small real matrices.
 *
 * Eigenvalues are found with a Hessenberg reduction followed by the classic
 * Francis double-shift QR iteration (the same small-matrix kernel used by
 * Numerical Recipes).  The eigenvector is then obtained by one shifted inverse
 * iteration and a Rayleigh-quotient refinement.  Only the dominant pair is
 * ever needed, so unlike LAPACK dgeev we never form or back-transform a full
 * eigenvector matrix.
 */

#define A_(i, j) a[(i) * stride + (j)]
#define SIGN(a, b) ((b) >= 0.0 ? fabs(a) : -fabs(a))

static void hessenberg(double *a, int n, int stride)
{
    /* Gaussian-elimination Hessenberg reduction; only eigenvalues matter. */
    for (int m = 1; m < n - 1; ++m) {
        double scale = 0.0;
        for (int i = m; i < n; ++i)
            scale += fabs(A_(i, m - 1));

        if (scale == 0.0)
            continue;

        for (int i = m; i < n; ++i)
            A_(i, m - 1) /= scale;

        double h = 0.0;
        for (int i = m; i < n; ++i)
            h += A_(i, m - 1) * A_(i, m - 1);

        double g = sqrt(h);
        if (A_(m, m - 1) > 0.0)
            g = -g;
        h -= A_(m, m - 1) * g;
        A_(m, m - 1) -= g;

        for (int j = m; j < n; ++j) {
            double f = 0.0;
            for (int i = m; i < n; ++i)
                f += A_(i, m - 1) * A_(i, j);
            f /= h;
            for (int i = m; i < n; ++i)
                A_(i, j) -= f * A_(i, m - 1);
        }

        for (int i = 0; i < n; ++i) {
            double f = 0.0;
            for (int j = m; j < n; ++j)
                f += A_(i, j) * A_(j, m - 1);
            f /= h;
            for (int j = m; j < n; ++j)
                A_(i, j) -= f * A_(j, m - 1);
        }

        A_(m, m - 1) = scale * g;
        for (int i = m + 1; i < n; ++i)
            A_(i, m - 1) = 0.0;
    }
}

static int hqr(double *a, int n, int stride, double *wr, double *wi)
{
    /* Francis double-shift QR on an upper Hessenberg matrix (1-based hqr). */
    double anorm = 0.0;
    for (int i = 1; i <= n; ++i)
        for (int j = (i > 1 ? i - 1 : 1); j <= n; ++j)
            anorm += fabs(A_(i, j));

    int nn = n;
    double t = 0.0;

    while (nn >= 1) {
        int its = 0;
        int l;
        do {
            for (l = nn; l >= 2; --l) {
                double s = fabs(A_(l - 1, l - 1)) + fabs(A_(l, l));
                if (s == 0.0)
                    s = anorm;
                if (fabs(A_(l, l - 1)) + s == s) {
                    A_(l, l - 1) = 0.0;
                    break;
                }
            }

            double x = A_(nn, nn);
            if (l == nn) {
                wr[nn - 1] = x + t;
                wi[nn - 1] = 0.0;
                --nn;
            } else {
                double y = A_(nn - 1, nn - 1);
                double w = A_(nn, nn - 1) * A_(nn - 1, nn);

                if (l == nn - 1) {
                    double p = 0.5 * (y - x);
                    double q = p * p + w;
                    double z = sqrt(fabs(q));
                    x += t;

                    if (q >= 0.0) {
                        z = p + SIGN(z, p);
                        wr[nn - 2] = wr[nn - 1] = x + z;
                        if (z != 0.0)
                            wr[nn - 1] = x - w / z;
                        wi[nn - 2] = wi[nn - 1] = 0.0;
                    } else {
                        wr[nn - 2] = wr[nn - 1] = x + p;
                        wi[nn - 2] = -z;
                        wi[nn - 1] = z;
                    }
                    nn -= 2;
                } else {
                    if (its >= 80)
                        return -1;
                    if (its == 10 || its == 20) {
                        t += x;
                        for (int i = 1; i <= nn; ++i)
                            A_(i, i) -= x;
                        double s = fabs(A_(nn, nn - 1)) + fabs(A_(nn - 1, nn - 2));
                        y = x = 0.75 * s;
                        w = -0.4375 * s * s;
                    }
                    ++its;

                    int m;
                    for (m = nn - 2; m >= l; --m) {
                        double z = A_(m, m);
                        double r = x - z;
                        double s = y - z;
                        double p = (r * s - w) / A_(m + 1, m) + A_(m, m + 1);
                        double q = A_(m + 1, m + 1) - z - r - s;
                        double rr = A_(m + 2, m + 1);
                        double ss = fabs(p) + fabs(q) + fabs(rr);
                        p /= ss;
                        q /= ss;
                        rr /= ss;
                        if (m == l)
                            break;
                        double u = fabs(A_(m, m - 1)) * (fabs(q) + fabs(rr));
                        double v = fabs(p) * (fabs(A_(m - 1, m - 1)) + fabs(z) +
                                              fabs(A_(m + 1, m + 1)));
                        if (u + v == v)
                            break;
                    }

                    for (int i = m + 2; i <= nn; ++i) {
                        A_(i, i - 2) = 0.0;
                        if (i != m + 2)
                            A_(i, i - 3) = 0.0;
                    }

                    for (int k = m; k <= nn - 1; ++k) {
                        double p, q, r;
                        if (k != m) {
                            p = A_(k, k - 1);
                            q = A_(k + 1, k - 1);
                            r = 0.0;
                            if (k != nn - 1)
                                r = A_(k + 2, k - 1);
                            double xnorm = fabs(p) + fabs(q) + fabs(r);
                            if (xnorm != 0.0) {
                                p /= xnorm;
                                q /= xnorm;
                                r /= xnorm;
                            }
                        } else {
                            p = A_(k, k - 1);
                            q = A_(k + 1, k - 1);
                            r = 0.0;
                            if (k != nn - 1)
                                r = A_(k + 2, k - 1);
                        }

                        double s = SIGN(sqrt(p * p + q * q + r * r), p);
                        if (s != 0.0) {
                            double xnorm;
                            if (k == m) {
                                if (l != m)
                                    A_(k, k - 1) = -A_(k, k - 1);
                            } else {
                                xnorm = fabs(p) + fabs(q) + fabs(r);
                                A_(k, k - 1) = -s * xnorm;
                            }
                            p += s;
                            double xx = p / s;
                            double yy = q / s;
                            double zz = r / s;
                            q /= p;
                            r /= p;

                            for (int j = k; j <= nn; ++j) {
                                p = A_(k, j) + q * A_(k + 1, j);
                                if (k != nn - 1) {
                                    p += r * A_(k + 2, j);
                                    A_(k + 2, j) -= p * zz;
                                }
                                A_(k + 1, j) -= p * yy;
                                A_(k, j) -= p * xx;
                            }

                            int mmin = nn < k + 3 ? nn : k + 3;
                            for (int i = l; i <= mmin; ++i) {
                                p = xx * A_(i, k) + yy * A_(i, k + 1);
                                if (k != nn - 1) {
                                    p += zz * A_(i, k + 2);
                                    A_(i, k + 2) -= p * r;
                                }
                                A_(i, k + 1) -= p * q;
                                A_(i, k) -= p;
                            }
                        }
                    }
                }
            }
        } while (l < nn - 1);
    }
    return 0;
}

static int solve_complex_system(const double *A, int n, double lr, double li,
                                double delta, double *xr, double *xi)
{
    /* Solve (A - (lambda+delta)I) x = b, with b a fixed generic vector. */
    double *br = (double *)malloc((size_t)n * n * sizeof(double));
    double *bi = (double *)malloc((size_t)n * n * sizeof(double));
    if (!br || !bi) {
        free(br);
        free(bi);
        return -1;
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            br[i * n + j] = A[i * n + j];
            bi[i * n + j] = 0.0;
        }
        br[i * n + i] -= lr + delta;
        bi[i * n + i] -= li;
        /* Deterministic generic right hand side. */
        xr[i] = 1.0 + 0.25 * (double)((i * 7 + 3) % 11);
        xi[i] = 0.125 * (double)((i * 5 + 1) % 7) - 0.375;
    }

    /* Complex LU with partial pivoting. */
    for (int k = 0; k < n; ++k) {
        int piv = k;
        double best = br[k * n + k] * br[k * n + k] +
                      bi[k * n + k] * bi[k * n + k];
        for (int i = k + 1; i < n; ++i) {
            double mag = br[i * n + k] * br[i * n + k] +
                         bi[i * n + k] * bi[i * n + k];
            if (mag > best) {
                best = mag;
                piv = i;
            }
        }

        if (piv != k) {
            for (int j = 0; j < n; ++j) {
                double tr = br[k * n + j], ti = bi[k * n + j];
                br[k * n + j] = br[piv * n + j];
                bi[k * n + j] = bi[piv * n + j];
                br[piv * n + j] = tr;
                bi[piv * n + j] = ti;
            }
            double tr = xr[k], ti = xi[k];
            xr[k] = xr[piv];
            xi[k] = xi[piv];
            xr[piv] = tr;
            xi[piv] = ti;
        }

        double dr = br[k * n + k];
        double di = bi[k * n + k];
        double dmag2 = dr * dr + di * di;
        if (dmag2 == 0.0) {
            /* This only happens for a numerically exact singular system.
               A tiny complex pivot keeps the subsequent arithmetic finite. */
            dr = 1e-300;
            di = 0.0;
            dmag2 = dr * dr;
        }

        for (int i = k + 1; i < n; ++i) {
            double nr = br[i * n + k], ni = bi[i * n + k];
            double fr = (nr * dr + ni * di) / dmag2;
            double fi = (ni * dr - nr * di) / dmag2;
            br[i * n + k] = fr;
            bi[i * n + k] = fi;
            if (fr == 0.0 && fi == 0.0)
                continue;
            for (int j = k + 1; j < n; ++j) {
                double mr = br[k * n + j], mi = bi[k * n + j];
                br[i * n + j] -= fr * mr - fi * mi;
                bi[i * n + j] -= fr * mi + fi * mr;
            }
            double mr = xr[k], mi = xi[k];
            xr[i] -= fr * mr - fi * mi;
            xi[i] -= fr * mi + fi * mr;
        }
    }

    /* Back substitution. */
    for (int i = n - 1; i >= 0; --i) {
        double sr = xr[i], si = xi[i];
        for (int j = i + 1; j < n; ++j) {
            double mr = br[i * n + j], mi = bi[i * n + j];
            sr -= mr * xr[j] - mi * xi[j];
            si -= mr * xi[j] + mi * xr[j];
        }
        double dr = br[i * n + i];
        double di = bi[i * n + i];
        double dmag2 = dr * dr + di * di;
        if (dmag2 == 0.0) {
            xr[i] = 0.0;
            xi[i] = 0.0;
        } else {
            xr[i] = (sr * dr + si * di) / dmag2;
            xi[i] = (si * dr - sr * di) / dmag2;
        }
    }

    double norm2 = 0.0;
    for (int i = 0; i < n; ++i)
        norm2 += xr[i] * xr[i] + xi[i] * xi[i];
    double norm = sqrt(norm2);
    if (!(norm > 0.0) || !isfinite(norm)) {
        free(br);
        free(bi);
        return -1;
    }
    for (int i = 0; i < n; ++i) {
        xr[i] /= norm;
        xi[i] /= norm;
    }

    free(br);
    free(bi);
    return 0;
}

static PyObject *dominant_eigenpair(PyObject *self, PyObject *arg)
{
    (void)self;
    PyArrayObject *arr = (PyArrayObject *)PyArray_FROM_OTF(
        arg, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (!arr)
        return NULL;

    int nd = PyArray_NDIM(arr);
    if (nd != 2 || PyArray_DIM(arr, 0) != PyArray_DIM(arr, 1)) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "expected a square 2-D array");
        return NULL;
    }

    npy_intp npy_n = PyArray_DIM(arr, 0);
    if (npy_n < 1 || npy_n > 100) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "unsupported matrix size");
        return NULL;
    }
    int n = (int)npy_n;
    const double *Ain = (const double *)PyArray_DATA(arr);

    if (n == 1) {
        PyObject *val = PyComplex_FromDoubles(Ain[0], 0.0);
        npy_intp dims[1] = {1};
        PyObject *vec = PyArray_SimpleNew(1, dims, NPY_COMPLEX128);
        if (val && vec) {
            double *v = (double *)PyArray_DATA((PyArrayObject *)vec);
            v[0] = 1.0;
            v[1] = 0.0;
        }
        Py_DECREF(arr);
        if (!val || !vec) {
            Py_XDECREF(val);
            Py_XDECREF(vec);
            return NULL;
        }
        return PyTuple_Pack(2, val, vec);
    }

    int stride = n + 1;
    double *a = (double *)calloc((size_t)(n + 1) * stride, sizeof(double));
    double *wr = (double *)malloc((size_t)n * sizeof(double));
    double *wi = (double *)malloc((size_t)n * sizeof(double));
    if (!a || !wr || !wi) {
        free(a);
        free(wr);
        free(wi);
        Py_DECREF(arr);
        return PyErr_NoMemory();
    }

    /* Copy into a 1-based matrix, as the QR kernel expects. */
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            a[(i + 1) * stride + (j + 1)] = Ain[i * n + j];

    hessenberg(a, n, stride);
    int ok = (hqr(a, n, stride, wr, wi) == 0);

    double lamr = 0.0, lami = 0.0;
    if (ok) {
        int best = 0;
        double bestmag = -1.0;
        for (int i = 0; i < n; ++i) {
            double mag = wr[i] * wr[i] + wi[i] * wi[i];
            if (mag > bestmag) {
                bestmag = mag;
                best = i;
            }
        }
        lamr = wr[best];
        lami = wi[best];
    }
    free(a);

    double *vr = (double *)malloc((size_t)n * sizeof(double));
    double *vi = (double *)malloc((size_t)n * sizeof(double));
    if (!vr || !vi) {
        free(wr);
        free(wi);
        free(vr);
        free(vi);
        Py_DECREF(arr);
        return PyErr_NoMemory();
    }

    int good = 0;
    if (ok) {
        double lamscale = hypot(lamr, lami);
        double delta = 1e-14 * (1.0 + lamscale);
        good = (solve_complex_system(Ain, n, lamr, lami, delta, vr, vi) == 0);
    }

    if (good) {
        /* Rayleigh quotient of the inverse-iteration vector. */
        double numr = 0.0, numi = 0.0, den = 0.0;
        for (int i = 0; i < n; ++i) {
            double avr = 0.0, avi = 0.0;
            for (int j = 0; j < n; ++j) {
                double m = Ain[i * n + j];
                avr += m * vr[j];
                avi += m * vi[j];
            }
            /* conj(v_i) * (A v)_i */
            numr += vr[i] * avr + vi[i] * avi;
            numi += vr[i] * avi - vi[i] * avr;
            den += vr[i] * vr[i] + vi[i] * vi[i];
        }
        if (den > 0.0) {
            lamr = numr / den;
            lami = numi / den;
        }

        /* Re-normalize (the Rayleigh step is harmless, but keeps things tidy). */
        double norm2 = 0.0;
        for (int i = 0; i < n; ++i)
            norm2 += vr[i] * vr[i] + vi[i] * vi[i];
        double norm = sqrt(norm2);
        if (norm > 0.0 && isfinite(norm)) {
            for (int i = 0; i < n; ++i) {
                vr[i] /= norm;
                vi[i] /= norm;
            }
        } else {
            good = 0;
        }
    }

    if (good) {
        /* Verify the per-component allclose-style residual before returning.
           If the small-matrix iteration was unusually ill conditioned, the
           Python wrapper falls back to LAPACK. */
        double atol = 1e-8, rtol = 1e-5;
        double lamscale = hypot(lamr, lami);
        for (int i = 0; i < n; ++i) {
            double avr = 0.0, avi = 0.0;
            for (int j = 0; j < n; ++j) {
                double m = Ain[i * n + j];
                avr += m * vr[j];
                avi += m * vi[j];
            }
            double rr = avr - (lamr * vr[i] - lami * vi[i]);
            double ri = avi - (lamr * vi[i] + lami * vr[i]);
            double lim = atol + rtol * hypot(lamr * vr[i] - lami * vi[i],
                                             lamr * vi[i] + lami * vr[i]);
            if (hypot(rr, ri) > lim) {
                good = 0;
                break;
            }
        }
        (void)lamscale;
    }

    free(wr);
    free(wi);

    if (!good) {
        free(vr);
        free(vi);
        Py_DECREF(arr);
        Py_RETURN_NONE;
    }

    PyObject *val = PyComplex_FromDoubles(lamr, lami);
    npy_intp dims[1] = {n};
    PyArrayObject *vec = (PyArrayObject *)PyArray_SimpleNew(1, dims, NPY_COMPLEX128);
    if (!val || !vec) {
        Py_XDECREF(val);
        Py_XDECREF(vec);
        free(vr);
        free(vi);
        Py_DECREF(arr);
        return NULL;
    }
    double *vout = (double *)PyArray_DATA(vec);
    for (int i = 0; i < n; ++i) {
        vout[2 * i] = vr[i];
        vout[2 * i + 1] = vi[i];
    }

    free(vr);
    free(vi);
    Py_DECREF(arr);
    return PyTuple_Pack(2, val, vec);
}

static PyMethodDef methods[] = {
    {"dominant_eigenpair", dominant_eigenpair, METH_O,
     "Return dominant eigenvalue/eigenvector (lambda, v) or None on failure."},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef module = {
    PyModuleDef_HEAD_INIT,
    "_eigen_fast",
    NULL,
    -1,
    methods
};

PyMODINIT_FUNC PyInit__eigen_fast(void)
{
    import_array();
    return PyModule_Create(&module);
}

