    double complex *h = (double complex *)malloc((size_t)n * n * sizeof(double complex));
    double complex *cs = (double complex *)malloc((size_t)n * sizeof(double complex));
    double complex *sn = (double complex *)malloc((size_t)n * sizeof(double complex));
    if (!h || !cs || !sn) {
        free(h);
        free(cs);
        free(sn);
        return -1;
    }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            h[i * n + j] = a[(i + 1) * stride + (j + 1)];

