        int l = 0;
        for (int k = m - 1; k >= 1; --k) {
            double d = cabs(h[k * n + k - 1]);
            double scale = cabs(h[(k - 1) * n + k - 1]) + cabs(h[k * n + k]);
            if (d <= 1e-14 * scale) {
