        double complex a11 = h[(m - 2) * n + m - 2];
        double complex a12 = h[(m - 2) * n + m - 1];
        double complex a21 = h[(m - 1) * n + m - 2];
        double complex a22 = h[(m - 1) * n + m - 1];
        double complex half = 0.5 * (a11 - a22);
        double complex disc = csqrt(half * half + a12 * a21);
